// PWA / home-screen icons of the admin — the ChiSetup CS mark (DESIGN-V3 §6, §8), rendered with
// Playwright from the repo's node_modules (same approach as docs/brand/v3/tools/render_brand.mjs).
// Sources: docs/brand/v3/mark.svg (rounded tile) and docs/brand/v3/tools/mark-full-bleed.svg
// (square, no rounding), both generated by docs/brand/v3/tools/gen_brand.py.
//   node frontend-admin/scripts/build-pwa-icons.mjs        (from the repo root)
// Writes frontend-admin/public/icons/*.png + icon.svg and frontend-admin/app/icon.svg (favicon).
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const admin = path.resolve(here, "..");
const root = path.resolve(admin, "..");
const { chromium } = await import(pathToFileURL(path.join(root, "node_modules/playwright/index.mjs")).href);

const read = (p) => fs.readFileSync(path.join(root, p), "utf8");
const mark = read("docs/brand/v3/mark.svg");
const bleed = read("docs/brand/v3/tools/mark-full-bleed.svg");

const sized = (svg, w, h) => svg.replace(/width="\d+" height="\d+"/, `width="${w}" height="${h}"`);

/** Full-bleed tile with the artwork (everything after the background rect) scaled about the centre. */
function bleedScaled(k) {
  const i = bleed.indexOf("<path");
  const j = bleed.lastIndexOf("</svg>");
  return `${bleed.slice(0, i)}<g transform="translate(256 256) scale(${k}) translate(-256 -256)">${bleed.slice(i, j)}</g></svg>`;
}

/** Android status-bar badge: white CS + brackets on transparent — Android paints only the alpha. */
function badge() {
  const paths = [...bleed.matchAll(/<path[^>]*d="([^"]+)"/g)].map((m) => `<path d="${m[1]}"/>`).join("");
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="512" height="512"><g fill="#FFFFFF">${paths}</g></svg>`;
}

const page = (body, w, h, transparent) => `<!doctype html><html><head><style>
html,body{margin:0;width:${w}px;height:${h}px;overflow:hidden;background:${transparent ? "transparent" : "#0E0E10"}}
svg{display:block}
</style></head><body>${body}</body></html>`;

const out = path.join(admin, "public", "icons");
fs.mkdirSync(out, { recursive: true });

const jobs = [
  // purpose "any": Chrome install dialog, desktop app icon — the rounded tile, transparent corners.
  { file: "icon-192.png", size: 192, svg: mark, transparent: true },
  { file: "icon-512.png", size: 512, svg: mark, transparent: true },
  // purpose "maskable": Android launcher crops to a circle of 80% — the bracket corners must stay
  // inside it, so the art is scaled to 0.74 on a full-bleed graphite square.
  { file: "icon-maskable-192.png", size: 192, svg: bleedScaled(0.74) },
  { file: "icon-maskable-512.png", size: 512, svg: bleedScaled(0.74) },
  // iOS home screen: iOS rounds the corners itself and never shows transparency → full bleed.
  { file: "apple-touch-icon-180.png", size: 180, svg: bleed },
  { file: "badge-96.png", size: 96, svg: badge(), transparent: true },
];

const browser = await chromium.launch();
for (const j of jobs) {
  const p = await browser.newPage({ viewport: { width: j.size, height: j.size }, deviceScaleFactor: 1 });
  await p.setContent(page(sized(j.svg, j.size, j.size), j.size, j.size, j.transparent));
  await p.screenshot({
    path: path.join(out, j.file),
    clip: { x: 0, y: 0, width: j.size, height: j.size },
    omitBackground: !!j.transparent,
  });
  await p.close();
  console.log("wrote public/icons/" + j.file);
}
await browser.close();

// Tab favicon (Next app router serves app/icon.svg as <link rel="icon">) and the offline page logo.
fs.writeFileSync(path.join(admin, "app", "icon.svg"), mark);
fs.writeFileSync(path.join(out, "icon.svg"), mark);
console.log("wrote app/icon.svg, public/icons/icon.svg");
